import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

// Import local logo images
import githubLogo from './images/github.jfif';
import facebookLogo from './images/facebook.jfif';
import googleLogo from './images/google.jfif';
import appleLogo from './images/apple.jfif';

const SignIn = () => {
  const navigate = useNavigate(); // React Router's hook to navigate
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('');
  const [rememberMe, setRememberMe] = useState(false); // State for the checkbox

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle sign-in logic here (e.g., API call)
    console.log('Name:', name);
    console.log('Password:', password);
    console.log('Role:', role);
    console.log('Remember Me:', rememberMe);
  };

  // Redirection function using React Router's navigate
  const redirectTo = (url) => {
    navigate(url); // React Router navigate function to handle internal routing
  };

  // Styles
  const containerStyle = {
    display: 'flex',
    justifyContent: 'center',   // Centers horizontally
    alignItems: 'center',       // Centers vertically
    height: '100vh',            // Full viewport height
    padding: '20px',
  };
  const borderStyle = {
    borderLeft: '2px solid #ccc',
    borderRight: '2px solid #ccc',
    padding: '20px',
    minWidth: '300px',          // Ensures the form has a minimum width
  };
  const formStyle = {
    padding: '20px',
    width: '100%',              // Make the form responsive inside the container
    maxWidth: '400px',          // Limit max width of the form
  };
  const buttonStyle = {
    backgroundColor: '#F27520',
    color: 'white',
    border: 'none',
    padding: '10px 20px',
    borderRadius: '5px',
    cursor: 'pointer',
    width: '50%',
    textAlign: 'center',
  };
  const logosContainerStyle = {
    display: 'flex',
    justifyContent: 'space-around',
    alignItems: 'center',
    marginTop: '20px',
  };
  const logoStyle = {
    width: '40px',
    height: 'auto',
    cursor: 'pointer', // Ensures hand pointer on hover
    transition: 'transform 0.2s ease', // Optional: add transition for smooth scaling effect
  };
  const linkStyle = {
    display: 'block',
    marginTop: '10px',
    textAlign: 'center',
  };

  // Optional hover effect for scaling (logo grows slightly when hovered)
  const handleHover = (e) => {
    e.target.style.transform = 'scale(1.1)';
  };

  const handleHoverEnd = (e) => {
    e.target.style.transform = 'scale(1)';
  };

  return (
    <div style={containerStyle}>
      <div style={borderStyle}>
        <div style={formStyle}>
          <h2>Sign In</h2>
          <div>
            <select value={role} onChange={(e) => setRole(e.target.value)} required>
              <option value="">Cadmax Login:-</option>
            </select>
            <br />
          </div>
          <form onSubmit={handleSubmit}>
            <div>
              <label>Name:</label>
              <br />
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Enter your username"
                required
              />
            </div>
            <div>
              <label>Password:</label>
              <br />
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter your password"
                required
              />
            </div>
            <div>
              <input
                type="checkbox"
                checked={rememberMe}
                onChange={(e) => setRememberMe(e.target.checked)}
              />
              <label> Keep me signed in</label>
            </div>
            <br />
            <button type="submit" style={buttonStyle}>Sign In</button>
          </form>
          
          {/* Horizontal Line */}
          <hr style={{ margin: '20px 0' }} />

          {/* Logos Section */}
          <div style={logosContainerStyle}>
            <img 
              src={githubLogo} 
              alt="GitHub" 
              style={logoStyle} 
              onClick={() => redirectTo('/github')} 
              onMouseEnter={handleHover} 
              onMouseLeave={handleHoverEnd}
            />
            <span style={{ borderLeft: '1px solid #ccc', height: '30px', margin: '0 10px' }}></span>

            <img 
              src={facebookLogo} 
              alt="Facebook" 
              style={logoStyle} 
              onClick={() => redirectTo('/facebook')} 
              onMouseEnter={handleHover} 
              onMouseLeave={handleHoverEnd}
            />
            <span style={{ borderLeft: '1px solid #ccc', height: '30px', margin: '0 10px' }}></span>

            <img 
              src={googleLogo} 
              alt="Google" 
              style={logoStyle} 
              onClick={() => redirectTo('/google')} 
              onMouseEnter={handleHover} 
              onMouseLeave={handleHoverEnd}
            />
            <span style={{ borderLeft: '1px solid #ccc', height: '30px', margin: '0 10px' }}></span>

            <img 
              src={appleLogo} 
              alt="Apple" 
              style={logoStyle} 
              onClick={() => redirectTo('/apple')} 
              onMouseEnter={handleHover} 
              onMouseLeave={handleHoverEnd}
            />
          </div>

          <div style={linkStyle}>
              No account? <a href="/create-account">Create an account</a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SignIn;
